interface Handler { void handle(Req q, Res s) throws Exception; }

static final Map<String, Handler> ROUTES = new LinkedHashMap<>();
static void get (String path, Handler h) { ROUTES.put("GET "  + path, h); }
static void post(String path, Handler h) { ROUTES.put("POST " + path, h); }

get("/",      (q, s) -> s.text("첫 화면\n"));
get("/hello", (q, s) -> {
    String name = q.param("name");
    s.text("안녕하세요 " + (name == null ? "손님" : name) + "\n");
});
get("/boom",  (q, s) -> { throw new IllegalStateException("일부러 터뜨린다"); });
post("/echo", (q, s) -> {
    s.type = "application/json; charset=UTF-8";
    s.text("{\"받은바이트\":" + q.body.length + "}\n");
});

Handler h = ROUTES.get(q.method + " " + q.path);
if (h == null) {
    boolean other = ROUTES.keySet().stream()
        .anyMatch(k -> k.endsWith(" " + q.path));   // 경로만 같은 키가 있나
    if (other) { r.status(405, "Method Not Allowed"); }
    else       { r.status(404, "Not Found"); }
}

try {
    h.handle(q, r);
} catch (Exception e) {
    r.status(500, "Internal Server Error");
    r.text("서버 오류\n");      // 예외 내용을 밖으로 보내지 않는다
    log(q, 500, e);              // 로그에만 남긴다
}

